(* [comment removed for export] *)
Lemma eager_grant_le : forall m (a n : word) h',
  BA.model_ivs_wf m ->
  bv_unsigned a + bv_unsigned n <= 2 ^ 64 ->
  vm_maps h' = (a, n) :: vm_maps (m_vmmaps m) ->
  vm_noaccess h' = vm_noaccess (m_vmmaps m) ->
