Lemma window_facts : forall r len,
  r mod 4096 = 0 -> len mod 4096 = 0 -> 0 < len -> 4096 <= r -> r + len <= 2 ^ 47 ->
  (r + len <= SHLO \/ SHHI <= r) ->
  window_ok (art_shlo r, art_shhi r len)
  /\ art_shhi r len - art_shlo r <= len / 8 + 8192
  /\ (forall x, art_shlo r <= x < art_shhi r len -> ~ (r <= x < r + len)).
