Lemma grant_parts : forall model (a : word) n,
  grant_ok_na_pin model a n = true ->
  bv_unsigned a mod 4096 = 0 /\ 0 < bv_unsigned a /\ bv_unsigned a + n <= alloc_top (m_vmmaps model)
