Lemma apart_of_covered : forall l (a n : word) lo hi,
  region_free l a n = true -> 0 < bv_unsigned n -> lo < hi ->
  (forall x, lo <= x < hi -> BA.covered l x = true) ->
  bv_unsigned a + bv_unsigned n <= lo \/ hi <= bv_unsigned a.
